#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

#define MAX_HEADERS 64
#define MAX_HEADER_LEN 4096
#define MAX_BODY_SIZE (1024 * 1024)
#define RING_BUF_SIZE 4096

typedef struct {
    char *name;
    char *value;
} http_header_t;

typedef struct {
    char method[16];
    char path[2048];
    http_header_t headers[MAX_HEADERS];
    int header_count;
    char *body;
    size_t body_len;
    size_t content_length;
} http_request_t;

typedef struct {
    unsigned char data[RING_BUF_SIZE];
    size_t read_pos;
    size_t write_pos;
    size_t count;
} ring_buffer_t;

/* Ring buffer operations - used for connection pooling */
static void ring_init(ring_buffer_t *rb) {
    memset(rb, 0, sizeof(*rb));
}

static size_t ring_available(ring_buffer_t *rb) {
    return rb->count;
}

static int ring_write(ring_buffer_t *rb, const unsigned char *data, size_t len) {
    if (len > RING_BUF_SIZE - rb->count) return -1;
    for (size_t i = 0; i < len; i++) {
        rb->data[rb->write_pos] = data[i];
        rb->write_pos = (rb->write_pos + 1) % RING_BUF_SIZE;
    }
    rb->count += len;
    return 0;
}

static size_t ring_read(ring_buffer_t *rb, unsigned char *out, size_t max_len) {
    size_t to_read = (max_len < rb->count) ? max_len : rb->count;
    for (size_t i = 0; i < to_read; i++) {
        out[i] = rb->data[rb->read_pos];
        rb->read_pos = (rb->read_pos + 1) % RING_BUF_SIZE;
    }
    rb->count -= to_read;
    return to_read;
}

/* Parse Content-Length header value safely */
static int parse_content_length(const char *value, size_t *out) {
    char *endptr;
    unsigned long long val;
    errno = 0;
    val = strtoull(value, &endptr, 10);
    if (errno != 0 || endptr == value || *endptr != '\0') return -1;
    if (val > MAX_BODY_SIZE) return -1;
    *out = (size_t)val;
    return 0;
}

/* Sanitize header value - remove dangerous characters */
static void sanitize_header_value(char *value) {
    for (char *p = value; *p; p++) {
        if (*p == '\r' || *p == '\n') *p = ' ';
    }
}

/* Parse a single header line into name:value */
static int parse_header_line(char *line, http_header_t *hdr) {
    char *colon = strchr(line, ':');
    if (!colon) return -1;
    *colon = '\0';
    hdr->name = line;
    hdr->value = colon + 1;
    /* Skip leading whitespace in value */
    while (*hdr->value == ' ' || *hdr->value == '\t') hdr->value++;
    sanitize_header_value(hdr->value);
    return 0;
}

/* Transfer-Encoding chunked body reader */
static int read_chunked_body(const char *input, size_t input_len,
                             char *body_buf, size_t buf_size,
                             size_t *total_written) {
    size_t pos = 0;
    *total_written = 0;

    while (pos < input_len) {
        /* Read chunk size (hex) */
        char size_str[20];
        int si = 0;
        while (pos < input_len && input[pos] != '\r' && si < 19) {
            size_str[si++] = input[pos++];
        }
        size_str[si] = '\0';

        /* Skip \r\n */
        if (pos + 1 < input_len && input[pos] == '\r' && input[pos+1] == '\n')
            pos += 2;
        else
            return -1;

        unsigned long chunk_size = strtoul(size_str, NULL, 16);
        if (chunk_size == 0) break; /* Final chunk */

        /* Validate: total written + this chunk must fit in buffer */
        if (*total_written + chunk_size > buf_size) return -1;

        /* Validate: chunk data available in input */
        if (pos + chunk_size > input_len) return -1;

        memcpy(body_buf + *total_written, input + pos, chunk_size);
        *total_written += chunk_size;
        pos += chunk_size;

        /* Skip trailing \r\n */
        if (pos + 1 < input_len && input[pos] == '\r' && input[pos+1] == '\n')
            pos += 2;
    }
    return 0;
}

/* Main request parser */
static int parse_request(const char *raw, size_t raw_len, http_request_t *req) {
    memset(req, 0, sizeof(*req));

    if (raw_len < 10) return -1;

    /* Copy to mutable buffer for tokenization */
    char *buf = malloc(raw_len + 1);
    if (!buf) return -1;
    memcpy(buf, raw, raw_len);
    buf[raw_len] = '\0';

    /* Parse request line */
    char *line_end = strstr(buf, "\r\n");
    if (!line_end) { free(buf); return -1; }
    *line_end = '\0';

    char *sp1 = strchr(buf, ' ');
    if (!sp1) { free(buf); return -1; }
    *sp1 = '\0';

    strncpy(req->method, buf, sizeof(req->method) - 1);
    char *path_start = sp1 + 1;
    char *sp2 = strchr(path_start, ' ');
    if (sp2) *sp2 = '\0';
    strncpy(req->path, path_start, sizeof(req->path) - 1);

    /* Parse headers */
    char *headers_start = line_end + 2;
    char *current = headers_start;

    while (current < buf + raw_len) {
        char *next_line = strstr(current, "\r\n");
        if (!next_line) break;
        if (next_line == current) { current = next_line + 2; break; } /* Empty line = end of headers */
        *next_line = '\0';

        if (req->header_count < MAX_HEADERS) {
            if (parse_header_line(current, &req->headers[req->header_count]) == 0) {
                req->header_count++;
            }
        }
        current = next_line + 2;
    }

    /* Find Content-Length */
    int has_content_length = 0;
    int has_chunked = 0;
    for (int i = 0; i < req->header_count; i++) {
        if (strcasecmp(req->headers[i].name, "Content-Length") == 0) {
            if (parse_content_length(req->headers[i].value, &req->content_length) == 0) {
                has_content_length = 1;
            }
        }
        if (strcasecmp(req->headers[i].name, "Transfer-Encoding") == 0) {
            if (strstr(req->headers[i].value, "chunked")) {
                has_chunked = 1;
            }
        }
    }

    /* Read body */
    size_t body_offset = (size_t)(current - buf);
    size_t remaining = (body_offset < raw_len) ? raw_len - body_offset : 0;

    if (has_chunked) {
        req->body = malloc(MAX_BODY_SIZE);
        if (!req->body) { free(buf); return -1; }
        if (read_chunked_body(raw + body_offset, remaining,
                             req->body, MAX_BODY_SIZE, &req->body_len) != 0) {
            free(req->body); req->body = NULL;
            free(buf); return -1;
        }
    } else if (has_content_length && req->content_length > 0) {
        if (remaining < req->content_length) {
            free(buf); return -1;
        }
        req->body = malloc(req->content_length);
        if (!req->body) { free(buf); return -1; }
        memcpy(req->body, raw + body_offset, req->content_length);
        req->body_len = req->content_length;
    }

    free(buf);
    return 0;
}

/* Response builder with template expansion */
static int build_response(http_request_t *req, char *resp_buf, size_t resp_size) {
    int offset = 0;
    offset += snprintf(resp_buf + offset, resp_size - offset,
                      "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n");

    /* Template: echo back the path and selected headers */
    offset += snprintf(resp_buf + offset, resp_size - offset,
                      "<html><body><h1>Request received</h1>\n");
    offset += snprintf(resp_buf + offset, resp_size - offset,
                      "<p>Path: %s</p>\n", req->path);

    /* Echo User-Agent if present */
    for (int i = 0; i < req->header_count; i++) {
        if (strcasecmp(req->headers[i].name, "User-Agent") == 0) {
            offset += snprintf(resp_buf + offset, resp_size - offset,
                              "<p>UA: %s</p>\n", req->headers[i].value);
        }
        if (strcasecmp(req->headers[i].name, "X-Request-Id") == 0) {
            offset += snprintf(resp_buf + offset, resp_size - offset,
                              "<p>ReqID: %s</p>\n", req->headers[i].value);
        }
    }

    if (req->body && req->body_len > 0) {
        /* Reflect body content in response for debugging */
        size_t preview_len = req->body_len < 256 ? req->body_len : 256;
        offset += snprintf(resp_buf + offset, resp_size - offset,
                          "<p>Body (%zu bytes): ", req->body_len);
        /* Safe: check that offset is valid and enough space remains */
        if (offset > 0 && (size_t)offset + preview_len + 10 < resp_size) {
            memcpy(resp_buf + offset, req->body, preview_len);
            offset += preview_len;
        }
        offset += snprintf(resp_buf + offset, resp_size - offset, "</p>\n");
    }

    offset += snprintf(resp_buf + offset, resp_size - offset, "</body></html>");
    return offset;
}

/* Connection handler with request routing */
static int handle_connection(const char *input, size_t input_len) {
    http_request_t req;
    char response[8192];

    if (parse_request(input, input_len, &req) != 0) {
        fprintf(stderr, "Failed to parse request\n");
        return -1;
    }

    int resp_len = build_response(&req, response, sizeof(response));

    /* Write response - clamp to buffer size */
    if (resp_len > 0 && (size_t)resp_len <= sizeof(response)) {
        fwrite(response, 1, resp_len, stdout);
    }

    if (req.body) free(req.body);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <request_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    if (fsize <= 0 || fsize > 65536) {
        fclose(f);
        fprintf(stderr, "Invalid file size\n");
        return 1;
    }
    fseek(f, 0, SEEK_SET);

    char *data = malloc(fsize);
    if (!data) { fclose(f); return 1; }
    if (fread(data, 1, fsize, f) != (size_t)fsize) {
        free(data); fclose(f); return 1;
    }
    fclose(f);

    handle_connection(data, fsize);

    free(data);
    return 0;
}
